import math
from scipy.optimize import fsolve

def archimedean_spiral(b, phi):
    r = b * phi
    return r * math.cos(phi), r * math.sin(phi)

def target_distance(b, phi, tx, ty):
    sx, sy = archimedean_spiral(b, phi)
    return math.sqrt((sx - tx)**2 + (sy - ty)**2)

def solve(b, tx, ty):
    def equation(phi):
        sx, sy = archimedean_spiral(b, phi)
        dx, dy = archimedean_spiral(b, phi + math.pi / (2 * b))
        return (tx - sx) * dy - (ty - sy) * dx

    phi_initial_guess = math.sqrt(tx**2 + ty**2) / b
    phi_solution = fsolve(equation, phi_initial_guess)[0]

    return archimedean_spiral(b, phi_solution)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    b = float(data[0])
    tx = float(data[1])
    ty = float(data[2])

    x, y = solve(b, tx, ty)
    print(f"{x:.10f} {y:.10f}")

if __name__ == "__main__":
    main()
